use vstd::prelude::*;

verus! {

// Helper spec: checks if n has no divisor in the range [start, end)
spec fn has_no_divisor_in_range(n: int, start: int, end: int) -> bool {
    forall|j: int| start <= j < end ==> n % j != 0
}

// Spec function defining primality
spec fn is_prime_spec(n: int) -> bool {
    n >= 2 && has_no_divisor_in_range(n, 2, n)
}

fn is_prime(n: i8) -> (result: bool)
    ensures
        result == is_prime_spec(n as int),
{
    // Handle cases where n < 2
    if n < 2 {
        return false;
    }
    
    // Check divisors from 2 to n-1
    let mut k: i8 = 2;
    while k < n
        invariant
            n >= 2,
            2 <= k <= n,
            has_no_divisor_in_range(n as int, 2, k as int),
        decreases n - k,
    {
        if n % k == 0 {
            // Found a divisor, so n is not prime
            assert(n % k == 0 && 2 <= k < n);
            assert(!has_no_divisor_in_range(n as int, 2, n as int));
            return false;
        }
        k = k + 1;
    }
    
    // Loop completed: k == n and no divisor found in [2, n)
    assert(k == n);
    assert(has_no_divisor_in_range(n as int, 2, n as int));
    true
}

} // verus!

